import * as React from 'react'
import { Users, Wifi, WifiOff, Loader2 } from 'lucide-react'
import { useUIConfig } from '@/components/ui/config-provider'
import { clamp, productURL } from '@/components/ui/product-utils'
import { cn } from '@/lib/utils'

export interface PresenceUser {
  id: string
  name: string
  avatar?: string
  color?: string
  status?: 'online' | 'away' | 'offline'
  typing?: boolean
  cursor?: { x: number; y: number }
  lastSeen?: number
}
export interface PresenceProps extends React.ComponentProps<'section'> {
  users: PresenceUser[]
  currentUserId?: string
  connection?: 'online' | 'reconnecting' | 'offline'
  maxVisible?: number
  staleAfter?: number
  onCursorChange?: (point: { x: number; y: number } | null) => void
  renderAvatar?: (user: PresenceUser) => React.ReactNode
  label?: string
}
interface PresenceContext extends Pick<
  PresenceProps,
  'currentUserId' | 'onCursorChange' | 'renderAvatar'
> {
  users: PresenceUser[]
  maxVisible: number
  connection: 'online' | 'reconnecting' | 'offline'
}
const Context = React.createContext<PresenceContext | null>(null)
const usePresence = () => {
  const c = React.useContext(Context)
  if (!c) throw new Error('Presence parts need Presence.')
  return c
}
/** Presents application-supplied presence; no hosted service or transport is assumed. */
export function Presence({
  users,
  currentUserId,
  connection = 'online',
  maxVisible = 5,
  staleAfter = 30000,
  onCursorChange,
  renderAvatar,
  label = 'Team presence',
  className,
  children,
  ...props
}: PresenceProps) {
  const [now, setNow] = React.useState(Date.now)
  React.useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), clamp(staleAfter, 1000, 10000))
    return () => clearInterval(timer)
  }, [staleAfter])
  const valid =
    users.every((user) => user.id && user.name) &&
    new Set(users.map((user) => user.id)).size === users.length
  const active = users.filter(
    (user) =>
      user.status !== 'offline' &&
      (user.lastSeen === undefined ||
        (Number.isFinite(user.lastSeen) && now - user.lastSeen <= clamp(staleAfter, 0, 86400000))),
  )
  return (
    <Context.Provider
      value={{
        users: active,
        currentUserId,
        connection,
        maxVisible: Math.floor(clamp(maxVisible, 1, 30)),
        onCursorChange,
        renderAvatar,
      }}
    >
      <section
        {...props}
        data-slot="presence"
        aria-label={label}
        className={cn('w-full min-w-0 space-y-3', className)}
      >
        {!valid ? (
          <p role="alert" className="text-sm text-destructive">
            Presence users need unique IDs and names.
          </p>
        ) : (
          (children ?? (
            <>
              <PresenceAvatars />
              <PresenceCanvas />
              <PresenceTyping />
            </>
          ))
        )}
      </section>
    </Context.Provider>
  )
}
/** Online participants, overflow count and reconnect status, with native-name tooltips. */
export function PresenceAvatars() {
  const c = usePresence()
  return (
    <div className="flex flex-wrap items-center gap-3">
      <Users className="size-4 text-muted-foreground" />
      <ul aria-label="Online participants" className="flex -space-x-2 rtl:space-x-reverse">
        {c.users.slice(0, c.maxVisible).map((user) => (
          <li
            key={user.id}
            title={`${user.name}${user.id === c.currentUserId ? ' (you)' : ''}${user.status === 'away' ? ' · away' : ''}`}
            className="relative flex size-9 shrink-0 items-center justify-center rounded-full border-2 border-background bg-muted text-xs font-medium"
            aria-label={`${user.name}${user.status === 'away' ? ', away' : ''}`}
          >
            {c.renderAvatar ? (
              c.renderAvatar(user)
            ) : user.avatar && productURL(user.avatar, true) ? (
              <img src={user.avatar} alt="" className="size-full rounded-full object-cover" />
            ) : (
              user.name
                .split(/\s+/)
                .map((part) => part[0])
                .slice(0, 2)
                .join('')
            )}
            <span
              aria-hidden
              className={cn(
                'absolute bottom-0 end-0 size-2.5 rounded-full border border-background',
                user.status === 'away' ? 'bg-amber-500' : 'bg-emerald-600',
              )}
            />
          </li>
        ))}
      </ul>
      {c.users.length > c.maxVisible && (
        <span className="text-xs text-muted-foreground">+{c.users.length - c.maxVisible} more</span>
      )}
      <span
        role="status"
        className="ms-auto flex items-center gap-1.5 text-xs text-muted-foreground"
      >
        {c.connection === 'online' ? (
          <Wifi className="size-3.5" />
        ) : c.connection === 'offline' ? (
          <WifiOff className="size-3.5" />
        ) : (
          <Loader2 className="size-3.5 animate-spin" />
        )}
        {c.connection}
      </span>
    </div>
  )
}
/** Coordinate-normalized cursor surface. The application publishes and receives presence events. */
export function PresenceCanvas({ className, children, ...props }: React.ComponentProps<'div'>) {
  const c = usePresence(),
    frame = React.useRef<number | null>(null),
    pending = React.useRef<{ x: number; y: number } | null>(null),
    publish = React.useRef(c.onCursorChange),
    config = useUIConfig()
  React.useLayoutEffect(() => {
    publish.current = c.onCursorChange
  }, [c.onCursorChange])
  React.useEffect(
    () => () => {
      if (frame.current !== null) cancelAnimationFrame(frame.current)
      publish.current?.(null)
    },
    [],
  )
  return (
    <div
      {...props}
      dir="ltr"
      data-slot="presence-canvas"
      className={cn(
        'relative min-h-48 overflow-hidden rounded-xl border bg-muted/20 bg-[radial-gradient(var(--border)_1px,transparent_1px)] [background-size:20px_20px]',
        className,
      )}
      onPointerMove={(event) => {
        props.onPointerMove?.(event)
        if (event.defaultPrevented || c.connection !== 'online') return
        const box = event.currentTarget.getBoundingClientRect()
        pending.current = {
          x: clamp((event.clientX - box.left) / box.width, 0, 1),
          y: clamp((event.clientY - box.top) / box.height, 0, 1),
        }
        if (frame.current === null)
          frame.current = requestAnimationFrame(() => {
            frame.current = null
            c.onCursorChange?.(pending.current)
          })
      }}
      onPointerLeave={(event) => {
        props.onPointerLeave?.(event)
        if (frame.current !== null) cancelAnimationFrame(frame.current)
        frame.current = null
        c.onCursorChange?.(null)
      }}
    >
      <div dir={config.direction}>
        {children ?? (
          <p className="p-5 text-xs text-muted-foreground">
            Move your pointer here. Remote cursors are supplied by your application.
          </p>
        )}
      </div>
      {c.users
        .filter((user) => user.id !== c.currentUserId && user.cursor)
        .map((user) => (
          <div
            key={user.id}
            data-slot="presence-cursor"
            data-user-id={user.id}
            aria-hidden="true"
            className="pointer-events-none absolute z-10 max-w-32 motion-safe:transition-[left,top]"
            style={{
              left: `${clamp(user.cursor!.x, 0, 1) * 100}%`,
              top: `${clamp(user.cursor!.y, 0, 1) * 100}%`,
              color: /^#[\da-f]{6}$/i.test(user.color ?? '') ? user.color : '#5579bd',
            }}
          >
            <svg
              aria-hidden
              width="18"
              height="22"
              viewBox="0 0 18 22"
              style={{
                transformOrigin: 'top left',
                transform: `scale(${user.cursor!.x > 0.95 ? -1 : 1},${user.cursor!.y > 0.9 ? -1 : 1})`,
              }}
            >
              <path
                d="M1 1v17l5-4 4 7 3-2-4-6 7-2Z"
                fill="currentColor"
                stroke="var(--background)"
              />
            </svg>
            <span
              className="absolute block max-w-32 truncate whitespace-nowrap rounded-md border bg-background px-2 py-1 text-[11px] text-foreground shadow-sm"
              style={{
                top: user.cursor!.y > 0.75 ? '-2rem' : '1.5rem',
                ...(user.cursor!.x > 0.7 ? { right: '.25rem' } : { left: '.75rem' }),
              }}
            >
              {user.name}
            </span>
          </div>
        ))}
    </div>
  )
}
/** Announces supplied typing state without pretending to establish a realtime connection. */
export function PresenceTyping() {
  const c = usePresence(),
    names = c.users
      .filter((user) => user.typing && user.id !== c.currentUserId)
      .map((user) => user.name)
  return (
    <p role="status" aria-live="polite" className="min-h-5 text-xs text-muted-foreground">
      {names.length
        ? `${names.slice(0, 3).join(', ')}${names.length > 3 ? ' and others' : ''} ${names.length === 1 ? 'is' : 'are'} typing…`
        : 'No one is typing.'}
    </p>
  )
}

import { contrastForeground } from '@/lib/contrast'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { Direction } from 'radix-ui'
export interface UIConfig {
  density: 'comfortable' | 'compact'
  direction: 'ltr' | 'rtl'
  locale: string
}
const ConfigContext = React.createContext<UIConfig>({
  density: 'comfortable',
  direction: 'ltr',
  locale: 'en-US',
})
const PortalContext = React.createContext<HTMLElement | null>(null)
export const usePortalContainer = () => React.useContext(PortalContext) ?? undefined
export const useUIConfig = () => React.useContext(ConfigContext)
export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
  density?: UIConfig['density']
  direction?: UIConfig['direction']
  locale?: string
  accent?: string
  radius?: number
}
export function ConfigProvider({
  density: providedDensity,
  direction: providedDirection,
  locale: providedLocale,
  accent,
  radius,
  children,
  style,
  className,
  ...props
}: ConfigProviderProps) {
  const parent = useUIConfig(),
    density = providedDensity ?? parent.density,
    direction = providedDirection ?? parent.direction,
    locale = providedLocale ?? parent.locale
  const [portal, setPortal] = React.useState<HTMLDivElement | null>(null)
  return (
    <ConfigContext.Provider value={{ density, direction, locale }}>
      <PortalContext.Provider value={portal}>
        <Direction.Provider dir={direction}>
          <div
            dir={direction}
            lang={locale}
            data-density={density}
            className={cn('ergon-root', className)}
            style={
              {
                '--ergon-control-height': density === 'compact' ? '30px' : '2.25rem',
                '--ergon-control-py': density === 'compact' ? '0.25rem' : '0.5rem',
                ...(accent
                  ? {
                      '--primary': accent,
                      '--ring': accent,
                      '--primary-foreground': contrastForeground(accent),
                    }
                  : {}),
                ...(radius !== undefined ? { '--radius': `${radius}px` } : {}),
                ...style,
              } as React.CSSProperties
            }
            {...props}
          >
            {children}
            <div ref={setPortal} data-ergon-portals="" style={{ display: 'contents' }} />
          </div>
        </Direction.Provider>
      </PortalContext.Provider>
    </ConfigContext.Provider>
  )
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from 'react'
import { useControllableState } from '@/components/ui/util'

/** Runs the latest cancellable action without publishing stale results after unmount. */
export function useAsyncAction() {
  const active = React.useRef<AbortController | null>(null)
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState('')
  React.useEffect(
    () => () => {
      active.current?.abort()
      active.current = null
    },
    [],
  )
  const cancel = React.useCallback(() => {
    active.current?.abort()
    active.current = null
    setBusy(false)
  }, [])
  const run = React.useCallback(async <T>(task: (signal: AbortSignal) => T | Promise<T>) => {
    active.current?.abort()
    const controller = new AbortController()
    active.current = controller
    setBusy(true)
    setError('')
    try {
      const value = await task(controller.signal)
      if (!controller.signal.aborted && active.current === controller) return value
    } catch (failure) {
      if (!controller.signal.aborted && active.current === controller)
        setError(failure instanceof Error ? failure.message : 'The action failed.')
    } finally {
      if (active.current === controller) {
        active.current = null
        setBusy(false)
      }
    }
    return undefined
  }, [])
  return { busy, error, run, cancel, clearError: () => setError('') }
}

/** Bounded immutable history for controlled or uncontrolled editors. */
export function useEditorHistory<T>({
  value,
  defaultValue,
  onChange,
  limit = 50,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
  limit?: number
}) {
  const [current, setCurrent] = useControllableState({ value, defaultValue, onChange })
  const [past, setPast] = React.useState<T[]>([])
  const [future, setFuture] = React.useState<T[]>([])
  const expected = React.useRef(current)
  React.useEffect(() => {
    if (value !== undefined && value !== expected.current) {
      expected.current = value
      setPast([])
      setFuture([])
    }
  }, [value])
  const apply = (next: T) => {
    expected.current = next
    setCurrent(next)
  }
  return {
    value: current,
    canUndo: past.length > 0,
    canRedo: future.length > 0,
    commit(next: T) {
      if (Object.is(next, current)) return
      setPast((previous) => [...previous, current].slice(-Math.max(1, Math.min(100, limit))))
      setFuture([])
      apply(next)
    },
    undo() {
      if (!past.length) return
      setPast(past.slice(0, -1))
      setFuture([current, ...future])
      apply(past[past.length - 1])
    },
    redo() {
      if (!future.length) return
      setPast([...past, current])
      setFuture(future.slice(1))
      apply(future[0])
    },
  }
}

/** Accepts explicit web/blob/image URLs and relative paths, never executable protocols. */
export function productURL(value: string, image = false): string | undefined {
  const clean = value.trim()
  if (
    !clean ||
    [...clean].some((character) => character.charCodeAt(0) <= 32 || character.charCodeAt(0) === 127)
  )
    return
  if (image && /^data:image\/(?:png|jpeg|webp|gif);base64,[\da-z+/=]+$/i.test(clean)) return clean
  try {
    const url = new URL(clean, 'https://ergon.invalid/')
    if (['http:', 'https:'].includes(url.protocol) || (image && url.protocol === 'blob:'))
      return clean
  } catch {
    /* Invalid input remains inert. */
  }
}
export const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, Number.isFinite(value) ? value : min))
/** Creates client-side entity IDs in secure and plain-HTTP browser contexts. */
export const productId = () => {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID()
  const bytes = globalThis.crypto.getRandomValues(new Uint8Array(16))
  bytes[6] = (bytes[6] & 15) | 64
  bytes[8] = (bytes[8] & 63) | 128
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
}

import * as React from 'react'
import { breakpoints, type Breakpoint } from '@/lib/responsive'
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}) {
  const [internal, setInternal] = React.useState(defaultValue)
  const current = value === undefined ? internal : value
  const currentRef = React.useRef(current),
    valueRef = React.useRef(value),
    changeRef = React.useRef(onChange)
  currentRef.current = current
  valueRef.current = value
  changeRef.current = onChange
  const set = React.useCallback((next: T | ((previous: T) => T)) => {
    const previous = currentRef.current
    const result = typeof next === 'function' ? (next as (previous: T) => T)(previous) : next
    if (Object.is(previous, result)) return
    currentRef.current = result
    if (valueRef.current === undefined) setInternal(result)
    changeRef.current?.(result)
  }, [])
  return [current, set] as const
}
export function useMediaQuery(query: string) {
  const [matches, setMatches] = React.useState(
    () => typeof window !== 'undefined' && window.matchMedia(query).matches,
  )
  React.useEffect(() => {
    const m = window.matchMedia(query)
    const update = () => setMatches(m.matches)
    update()
    m.addEventListener('change', update)
    return () => m.removeEventListener('change', update)
  }, [query])
  return matches
}
export function useDebouncedValue<T>(value: T, delay = 250) {
  const [debounced, set] = React.useState(value)
  React.useEffect(() => {
    const id = setTimeout(() => set(value), delay)
    return () => clearTimeout(id)
  }, [value, delay])
  return debounced
}
export async function copyToClipboard(text: string) {
  await navigator.clipboard.writeText(text)
}
export function useBreakpoints() {
  const [width, setWidth] = React.useState(() =>
    typeof window === 'undefined' ? 0 : window.innerWidth,
  )
  React.useEffect(() => {
    const update = () => setWidth(window.innerWidth)
    window.addEventListener('resize', update)
    return () => window.removeEventListener('resize', update)
  }, [])
  return Object.fromEntries(
    Object.entries(breakpoints).map(([key, min]) => [key, width >= min]),
  ) as Record<Breakpoint, boolean>
}

import type { CSSProperties } from 'react'
export const breakpoints = { xs: 0, sm: 640, md: 768, lg: 1024, xl: 1280, '2xl': 1536 } as const
export type Breakpoint = keyof typeof breakpoints
export type Responsive<T> = T | Partial<Record<Breakpoint, T>>
export function responsiveStyle<T>(value: Responsive<T> | undefined, name: string): CSSProperties {
  if (value === undefined) return {}
  const values = typeof value === 'object' && value !== null ? value : { xs: value }
  return Object.fromEntries(
    Object.entries(values).map(([key, v]) => [`--${name}-${key}`, v]),
  ) as CSSProperties
}
export const responsiveCSS = Object.entries(breakpoints)
  .map(([, min], index) => {
    const fallback = (name: string, initial: string) =>
      Object.keys(breakpoints)
        .slice(0, index + 1)
        .reduce((result, key) => `var(--${name}-${key},${result})`, initial)
    return `@media(min-width:${min}px){.ergon-col{width:calc(${fallback('span', '24')} / 24 * 100%);margin-inline-start:calc(${fallback('offset', '0')} / 24 * 100%);order:${fallback('order', '0')}}.ergon-flex{gap:${fallback('gap', '12px')};flex-direction:${fallback('direction', 'row')}}}`
  })
  .join('')
